// Renders a QR code into every .qr-svg[data-url] (qr.php). The SVG is generated by qrcode-generator
// from the URL string only, so inserting it as markup is safe.
document.querySelectorAll('.qr-svg[data-url]').forEach(box => {
    const qr = qrcode(0, 'M');
    qr.addData(box.dataset.url);
    qr.make();
    box.innerHTML = qr.createSvgTag({ cellSize: 4, margin: 2, scalable: true });
});
document.getElementById('btn-print')?.addEventListener('click', () => window.print());
